const body = $input.first().json.body || $input.first().json;
const data = body.data || {};
const key = data.key || {};
const env = process.env;

const businessName = env.BUSINESS_NAME || 'our business';
const evoUrl = (env.EVOLUTION_INTERNAL_URL || 'http://evolution-api.railway.internal:8080').replace(/\/$/, '');
const instance = body.instance || data.instanceName || '';
const text = data.message?.conversation || data.message?.extendedTextMessage?.text || '';
const remoteJid = key.remoteJid || '';
const isGroup = remoteJid.endsWith('@g.us');
const fromMe = key.fromMe === true;

const out = {
  route: 'ignore',
  chatId: remoteJid,
  number: remoteJid.split('@')[0],
  instance,
  pushName: data.pushName || '',
  text,
  sendUrl: `${evoUrl}/message/sendText/${encodeURIComponent(instance)}`,
  sendHeaders: { apikey: env.EVOLUTION_API_KEY || '', 'Content-Type': 'application/json' }
};

if (!text || fromMe || isGroup || !instance || !remoteJid) {
  return [{ json: out }];
}

const handoff = (env.HANDOFF_KEYWORD || 'human').toLowerCase();
if (text.toLowerCase().includes(handoff)) {
  out.route = 'handoff';
  out.replyText = env.HANDOFF_MESSAGE || `Thanks${out.pushName ? ' ' + out.pushName : ''}! A member of the ${businessName} team has been notified and will reply to you here shortly.`;
  out.sendBody = { number: out.number, text: out.replyText };
  return [{ json: out }];
}

const hours = (env.OFFICE_HOURS || '24/7').trim();
if (hours !== '24/7') {
  const m = hours.match(/^(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})$/);
  if (m) {
    const tz = env.GENERIC_TIMEZONE || 'UTC';
    const hm = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
    const [h, min] = hm.split(':').map(Number);
    const now = h * 60 + min;
    const start = (+m[1]) * 60 + (+m[2]);
    const end = (+m[3]) * 60 + (+m[4]);
    const open = start <= end ? (now >= start && now < end) : (now >= start || now < end);
    if (!open) {
      out.route = 'closed';
      out.replyText = env.OFFICE_CLOSED_MESSAGE || `Hi${out.pushName ? ' ' + out.pushName : ''}, thanks for contacting ${businessName}! We're currently closed (office hours: ${hours}). Leave your message here and we'll get back to you as soon as we reopen.`;
      out.sendBody = { number: out.number, text: out.replyText };
      return [{ json: out }];
    }
  }
}

out.route = 'ai';
return [{ json: out }];

const msg = $input.first().json;
const env = process.env;
const provider = (env.LLM_PROVIDER || 'anthropic').toLowerCase();
const apiKey = env.LLM_API_KEY || '';
const businessName = env.BUSINESS_NAME || 'our business';
const handoff = env.HANDOFF_KEYWORD || 'human';

const system = `You are the AI receptionist for ${businessName}, replying on WhatsApp. ${env.SYSTEM_PROMPT || 'Answer customer questions helpfully and honestly. If you do not know an answer, say so.'} Keep replies short and friendly (under 120 words, plain text, no markdown). If the customer asks to speak with a person, tell them to reply with the word "${handoff}" to reach the team.`;

let llmUrl, llmHeaders, llmBody;
if (provider === 'openai') {
  llmUrl = 'https://api.openai.com/v1/chat/completions';
  llmHeaders = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
  llmBody = {
    model: env.LLM_MODEL || 'gpt-4o-mini',
    max_tokens: 512,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: msg.text }
    ]
  };
} else {
  llmUrl = 'https://api.anthropic.com/v1/messages';
  llmHeaders = { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' };
  llmBody = {
    model: env.LLM_MODEL || 'claude-haiku-4-5-20251001',
    max_tokens: 512,
    system,
    messages: [{ role: 'user', content: msg.text }]
  };
}

return [{ json: { ...msg, provider, llmUrl, llmHeaders, llmBody } }];

const resp = $input.first().json;
const msg = $('Build LLM Request').first().json;

let reply = '';
if (msg.provider === 'openai') {
  reply = resp.choices?.[0]?.message?.content || '';
} else if (Array.isArray(resp.content)) {
  reply = resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
}

if (!reply) {
  const handoff = process.env.HANDOFF_KEYWORD || 'human';
  reply = `Sorry, I'm having trouble answering right now. Reply "${handoff}" and a member of our team will help you directly.`;
}

return [{ json: { sendUrl: msg.sendUrl, sendHeaders: msg.sendHeaders, sendBody: { number: msg.number, text: reply } } }];
